    /**
     * Method to retrieve the Note via NoteFetchOneSummary
     * @param 	summary NoteFetchOneSummary 
     * @return 	NoteFetchOneResponse
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    public Note getNote( NoteFetchOneSummary summary ) 
    throws ProcessingException, IllegalArgumentException {
    	
    	if( summary == null )
    		throw new IllegalArgumentException( "NoteFetchOneSummary arg cannot be null" );
    	
    	Note entity = null;
    	
        try {
        	// --------------------------------------
        	// validate the fetch one summary
        	// --------------------------------------    	
        	validator.validate( summary );    
        	
        	// --------------------------------------
        	// use queryGateway to send request to Find a Note
        	// --------------------------------------
        	CompletableFuture<Note> futureEntity = queryGateway.query(new FindNoteQuery( new LoadNoteFilter( summary.getNoteId() ) ), ResponseTypes.instanceOf(Note.class));
        	
        	entity = futureEntity.get();
        }
        catch( Exception exc ) {
            final String errMsg = "Unable to locate Note with id " + summary.getNoteId();
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return entity;
    }


